
const feed = document.getElementById("feed");

// CURTIR PUBLICAÇÕES
document.addEventListener("click", function(event) {
    if (event.target.classList.contains("like")) {
            const botao = event.target;
                    const post = botao.closest(".post");
                            const contador = post.querySelector(".likes strong");

                                    let curtidas = Number(
                                                contador.textContent.replace(/\D/g, "")
                                                        );

                                                                if (botao.classList.contains("liked")) {
                                                                            curtidas--;
                                                                                        botao.classList.remove("liked");
                                                                                                    botao.textContent = "♡";
                                                                                                            } else {
                                                                                                                        curtidas++;
                                                                                                                                    botao.classList.add("liked");
                                                                                                                                                botao.textContent = "♥";
                                                                                                                                                        }

                                                                                                                                                                contador.textContent = curtidas + " curtidas";
                                                                                                                                                                    }
                                                                                                                                                                    });

                                                                                                                                                                    // COMENTÁRIOS
                                                                                                                                                                    document.addEventListener("submit", function(event) {
                                                                                                                                                                        if (event.target.classList.contains("comment-form")) {
                                                                                                                                                                                event.preventDefault();

                                                                                                                                                                                        const input = event.target.querySelector("input");
                                                                                                                                                                                                const comentario = input.value.trim();

                                                                                                                                                                                                        if (comentario === "") return;

                                                                                                                                                                                                                const post = event.target.closest(".post");
                                                                                                                                                                                                                        const comentarios = post.querySelector(".comments");

                                                                                                                                                                                                                                const novoComentario = document.createElement("p");
                                                                                                                                                                                                                                        novoComentario.textContent = comentario;

                                                                                                                                                                                                                                                comentarios.appendChild(novoComentario);
                                                                                                                                                                                                                                                        input.value = "";
                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                            // ABRIR MODAL
                                                                                                                                                                                                                                                            const modal = document.getElementById("createModal");

                                                                                                                                                                                                                                                            document.getElementById("openCreate").addEventListener("click", function(e) {
                                                                                                                                                                                                                                                                e.preventDefault();
                                                                                                                                                                                                                                                                    modal.style.display = "flex";
                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                    // FECHAR MODAL
                                                                                                                                                                                                                                                                    document.getElementById("closeModal").addEventListener("click", function() {
                                                                                                                                                                                                                                                                        modal.style.display = "none";
                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                        // CRIAR PUBLICAÇÃO
                                                                                                                                                                                                                                                                        document.getElementById("publish").addEventListener("click", function() {
                                                                                                                                                                                                                                                                            const usuario = document.getElementById("username").value.trim();
                                                                                                                                                                                                                                                                                const imagem = document.getElementById("imageUrl").value.trim();
                                                                                                                                                                                                                                                                                    const legenda = document.getElementById("caption").value.trim();

                                                                                                                                                                                                                                                                                        if (!usuario || !imagem) {
                                                                                                                                                                                                                                                                                                alert("Preencha o usuário e a URL da imagem!");
                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                        const url = new URL(imagem);
                                                                                                                                                                                                                                                                                                                                if (!["http:", "https:"].includes(url.protocol)) {
                                                                                                                                                                                                                                                                                                                                            throw new Error("URL inválida");
                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                        } catch {
                                                                                                                                                                                                                                                                                                                                                                alert("Digite uma URL de imagem válida!");
                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                const post = document.createElement("article");
                                                                                                                                                                                                                                                                                                                                                                                    post.className = "post";

                                                                                                                                                                                                                                                                                                                                                                                        const cabecalho = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                            cabecalho.className = "post-header";

                                                                                                                                                                                                                                                                                                                                                                                                const nome = document.createElement("strong");
                                                                                                                                                                                                                                                                                                                                                                                                    nome.textContent = usuario;

                                                                                                                                                                                                                                                                                                                                                                                                        const foto = document.createElement("img");
                                                                                                                                                                                                                                                                                                                                                                                                            foto.src = "https://i.pravatar.cc/100?img=12";
                                                                                                                                                                                                                                                                                                                                                                                                                foto.alt = "Foto de perfil";

                                                                                                                                                                                                                                                                                                                                                                                                                    cabecalho.append(foto, nome);

                                                                                                                                                                                                                                                                                                                                                                                                                        const imagemPost = document.createElement("img");
                                                                                                                                                                                                                                                                                                                                                                                                                            imagemPost.className = "post-image";
                                                                                                                                                                                                                                                                                                                                                                                                                                imagemPost.src = imagem;
                                                                                                                                                                                                                                                                                                                                                                                                                                    imagemPost.alt = "Publicação";
                                                                                                                                                                                                                                                                                                                                                                                                                                        imagemPost.onerror = () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Não foi possível carregar essa imagem.");
                                                                                                                                                                                                                                                                                                                                                                                                                                                        post.remove();
                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                const acoes = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    acoes.className = "post-actions";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        acoes.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button class="like">♡</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button class="comment">💬</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button>➤</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <button class="save">♧</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const curtidas = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    curtidas.className = "likes";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        curtidas.innerHTML = "<strong>0 curtidas</strong>";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const texto = document.createElement("p");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                texto.className = "caption";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const nomeLegenda = document.createElement("strong");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        nomeLegenda.textContent = usuario + " ";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            texto.append(nomeLegenda, document.createTextNode(legenda));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const comentarios = document.createElement("div");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    comentarios.className = "comments";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const formulario = document.createElement("form");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formulario.className = "comment-form";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formulario.innerHTML = `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <input type="text" placeholder="Adicione um comentário...">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <button type="submit">Publicar</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    `;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        post.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cabecalho,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        imagemPost,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                acoes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        curtidas,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                texto,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        comentarios,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                formulario
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        feed.prepend(post);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            modal.style.display = "none";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("username").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("imageUrl").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("caption").value = "";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // SEGUIR USUÁRIOS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.querySelectorAll(".follow").forEach(botao => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.addEventListener("click", function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (botao.textContent === "Seguir") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botao.textContent = "Seguindo";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.style.color = "#888";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                botao.textContent = "Seguir";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.style.color = "#0095f6";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        